// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = keccak256("a");
        uint64 _sequenceNumber = 4;
        bytes32 _batcherHash = keccak256("b");
        uint256 _l1FeeOverhead = 10;
        uint256 _l1FeeScalar = 20;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        assertTrue(c.l1FeeScalar() == 20);
    }
}
